async function authorized(r,e){const email=r.headers.get('oai-authenticated-user-email');const id=r.headers.get('oai-authenticated-user-id');return Boolean(id&&email&&e.ADMIN_EMAIL&&email.toLowerCase()===e.ADMIN_EMAIL.toLowerCase())}
const json=(v,status=200,headers={})=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json','cache-control':'no-store',...headers}});
const defaults={products:[],phone:'5511997981891'};
async function preserveCatalog(bucket,catalog,key){
 const photos=[...new Set(catalog.products.map(p=>p.photo).filter(Boolean))];
 for(const path of photos){
  if(!/^\/images\/[a-zA-Z0-9-]+$/.test(path))throw Error('Invalid photo path');
  const id=path.slice(8),backupKey='backups/photos/'+id;
  if(await bucket.head(backupKey))continue;
  const photo=await bucket.get('photos/'+id);if(!photo)throw Error('Photo missing; catalog unchanged');
  await bucket.put(backupKey,photo.body,{httpMetadata:photo.httpMetadata});
 }
 await bucket.put(key,JSON.stringify(catalog),{httpMetadata:{contentType:'application/json'}});
 return key;
}
async function initialBackup(bucket,catalog){if(!(await bucket.head('backups/initial.json')))await preserveCatalog(bucket,catalog,'backups/initial.json')}
const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function binaryHeader(size,values){const b=new Uint8Array(size),v=new DataView(b.buffer);for(const[o,n,width]of values)width===2?v.setUint16(o,n,true):v.setUint32(o,n,true);return b}
async function* zipFiles(files){let offset=0;const central=[];const encoder=new TextEncoder();
 for(const f of files){const name=encoder.encode(f.name),bytes=await f.bytes(),crc=crc32(bytes),size=bytes.length;
 const header=binaryHeader(30,[[0,0x04034b50,4],[4,20,2],[6,0x800,2],[12,33,2],[14,crc,4],[18,size,4],[22,size,4],[26,name.length,2]]);
 central.push({name,crc,size,offset});yield header;yield name;yield bytes;offset+=header.length+name.length+size;
 }
 const centralStart=offset;
 for(const f of central){const header=binaryHeader(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[8,0x800,2],[14,33,2],[16,f.crc,4],[20,f.size,4],[24,f.size,4],[28,f.name.length,2],[42,f.offset,4]]);yield header;yield f.name;offset+=header.length+f.name.length}
 yield binaryHeader(22,[[0,0x06054b50,4],[8,central.length,2],[10,central.length,2],[12,offset-centralStart,4],[16,centralStart,4]]);
}
async function exportCatalog(bucket,catalog){
 const key='backups/catalog/'+new Date().toISOString().replace(/[:.]/g,'-')+'-'+crypto.randomUUID()+'.json';await preserveCatalog(bucket,catalog,key);
 const encoder=new TextEncoder(),manifest={format:'km-catalog-backup-v1',createdAt:new Date().toISOString(),snapshot:key,photos:[]};
 const files=[{name:'catalog.json',bytes:async()=>encoder.encode(JSON.stringify(catalog,null,2))}];
 for(const path of [...new Set(catalog.products.map(p=>p.photo))]){const id=path.slice(8),meta=await bucket.head('backups/photos/'+id);if(!meta)throw Error('Backup photo missing');const type=meta.httpMetadata?.contentType||'image/jpeg',extension=type==='image/png'?'png':type==='image/webp'?'webp':'jpg',name='photos/'+id+'.'+extension;manifest.photos.push({originalPath:path,file:name,contentType:type});files.push({name,bytes:async()=>{const photo=await bucket.get('backups/photos/'+id);if(!photo)throw Error('Backup photo missing');return new Uint8Array(await photo.arrayBuffer())}})}
 files.push({name:'manifest.json',bytes:async()=>encoder.encode(JSON.stringify(manifest,null,2))},{name:'LEIA-ME.txt',bytes:async()=>encoder.encode('Backup K&M\n\nO arquivo catalog.json contém todos os produtos e o contato da loja.\nA pasta photos contém as fotos.\nO manifest.json relaciona cada caminho original com sua foto.\nGuarde este ZIP fora do site, no computador ou em outro serviço.\nEle é uma cópia independente para recuperação; não altera o catálogo.\n')});
 const iterator=zipFiles(files);return new Response(new ReadableStream({async pull(controller){try{const {value,done}=await iterator.next();if(done)controller.close();else controller.enqueue(value)}catch(error){controller.error(error)}},async cancel(){await iterator.return()}}),{headers:{'content-type':'application/zip','content-disposition':'attachment; filename="catalogo-km-'+new Date().toISOString().slice(0,10)+'.zip"','cache-control':'no-store','x-content-type-options':'nosniff'}})
}

