let orderGroups=[];
function drawOrder(){
 $('orderList').innerHTML=orderGroups.length?orderGroups.map((g,i)=>'<section class="order-group"><div class="order-heading"><strong>'+esc(g.brand)+'</strong><div class="order-buttons"><button class="secondary" type="button" data-order-brand="'+i+'" data-direction="-1" '+(i===0?'disabled':'')+' aria-label="Mover marca '+esc(g.brand)+' para cima">↑</button><button class="secondary" type="button" data-order-brand="'+i+'" data-direction="1" '+(i===orderGroups.length-1?'disabled':'')+' aria-label="Mover marca '+esc(g.brand)+' para baixo">↓</button></div></div>'+g.products.map((p,j)=>'<div class="order-row"><span>'+esc(p.model)+' <small class="order-note">· '+esc(p.size)+'</small></span><div class="order-buttons"><button class="secondary" type="button" data-order-item="'+esc(p.id)+'" data-direction="-1" '+(j===0?'disabled':'')+' aria-label="Mover '+esc(p.model)+' para cima">↑</button><button class="secondary" type="button" data-order-item="'+esc(p.id)+'" data-direction="1" '+(j===g.products.length-1?'disabled':'')+' aria-label="Mover '+esc(p.model)+' para baixo">↓</button></div></div>').join('')+'</section>').join(''):'<p class="notice">Cadastre seu primeiro item para organizar o catálogo.</p>';
}
$('orderButton').onclick=()=>{orderGroups=[...new Set(data.products.map(p=>p.brand))].map(brand=>({brand,products:data.products.filter(p=>p.brand===brand)}));drawOrder();$('orderDialog').showModal()};
