function rankChart(title,rows){return '<section class="insight-chart"><h3>'+esc(title)+'</h3>'+(rows.length?rows.map(row=>'<div class="insight-rank"><div><span>'+esc(row.label)+'</span><b>'+row.count+'</b></div><div class="insight-track"><i style="width:'+Math.max(2,Math.round(row.count/Math.max(1,...rows.map(r=>r.count))*100))+'%"></i></div></div>').join(''):'<p class="notice">Ainda sem dados neste período.</p>')+'</section>'}
const categoryNames={all:'Todos',bestSellers:'Mais vendidos',budget:'Mais baratos',newArrivals:'Novidades'};
function renderInsights(s){const card=(label,n)=>'<div class="insight-card"><span>'+label+'</span><strong>'+n+'</strong></div>';$('insightsContent').innerHTML='<div class="insight-cards">'+card('Visitas históricas',s.visits)+card('Aberturas dos modelos',s.productViews)+card('Cliques de finalização',s.checkoutClicks)+card('Visitas com finalização',s.conversion+'%')+'</div><p class="notice">Cliques no WhatsApp são intenção de contato, não vendas ou pagamentos confirmados. Conversão: visitas com ao menos um clique ÷ visitas históricas. Relação entre cliques e aberturas dos modelos: '+s.viewClickRate+'%.</p>'+(s.limited?'<p class="notice">O período excedeu o limite de leitura. Escolha um período menor para conferir os dados completos.</p>':'')+'<div class="insight-charts">'+rankChart('Modelos mais visualizados',s.topViews)+rankChart('Modelos mais adicionados à sacola',s.topAdds)+rankChart('Abas e marcas mais acessadas',s.topCategories.map(r=>({...r,label:categoryNames[r.label]||r.label})))+rankChart('Termos mais pesquisados',s.topSearches)+rankChart('Visitas por dia',s.daily.map(r=>({label:r.day.split('-').reverse().join('/'),count:r.visitors})))+rankChart('Movimento por dia da semana',s.weekdays.map((n,i)=>({label:['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][i],count:n})))+rankChart('Movimento por hora · São Paulo',s.hours.map((n,i)=>({label:String(i).padStart(2,'0')+'h',count:n})).filter(r=>r.count>0))+'</div><p class="notice">Somente visitantes que aceitaram estatísticas entram nos indicadores. Visitas são sessões anônimas por dia; abas ou aparelhos diferentes podem contar separadamente. Adições contam ações de aumentar a quantidade. Buscas livres são agrupadas como “outras” ('+s.otherSearches+'); somente termos já existentes no catálogo aparecem aqui. Movimento considera interações consentidas.</p>';
 $('diagnosticsContent').innerHTML=s.diagnostics.length?s.diagnostics.map(d=>'<article class="diagnostic-row"><div><strong>'+esc(d.description)+'</strong><p>'+esc(d.area)+' · '+d.count+' ocorrência(s)</p><small>Primeira: '+formatDiagnosticDate(d.first)+'<br>Última: '+formatDiagnosticDate(d.last)+'</small></div><div><span class="diagnostic-state '+(d.status==='resolved'?'resolved':'')+'">'+(d.status==='resolved'?'Resolvido':'Em aberto')+'</span><button type="button" class="secondary" data-error-code="'+esc(d.code)+'" data-resolved="'+(d.status!=='resolved')+'">'+(d.status==='resolved'?'Reabrir':'Marcar como resolvido')+'</button></div></article>').join(''):'<p class="notice">Nenhuma ocorrência registrada neste período. Isso não garante ausência de falhas.</p>';
 $('insightsUpdated').textContent='Atualizado em '+formatDiagnosticDate(Date.now())+' · horário de São Paulo.';
}
function formatDiagnosticDate(t){return new Date(t).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'})}
